/*
 * dir_$alloc_overflow_page - put a long link's text on a page of its own
 *
 * Original address: 0x00E4E960
 * Size: 316 bytes (0x00E4E960 .. 0x00E4EA9B)
 * Generated by: Claude Opus 5.5
 *
 * A nested Pascal procedure of dir_$add_entry (no map symbol), called at
 * 0x00E4FEB0 when a type-4 entry's name and link text together exceed
 * 0x1B1 bytes.  Its only argument is status_ret ((0x8,A6), D2); `movea.l
 * (A6),A2' is the static link, and the parent's cells are ctx->handle
 * ((0x8,A2), D3/A3), ctx->link_len ((0x1C,A2)), ctx->link_data ((0x1E,A2))
 * and ctx->overflow_page ((-0xAA,A2), the page chosen).
 *
 * Blocks:
 *   0x00E4E96E-0x00E4E982  *status_ret = ok; page = handle->length / 0x400
 *                          - 1, the directory's last page
 *   0x00E4E986-0x00E4E9B0  walk down while the page's first word is 0; page
 *                          0 empty is CRASH_SYSTEM(&Naming_bad_request_
 *                          header_ver_err) (`pea (-0x3772,PC)' = 0x00E4B230)
 *   0x00E4E9B2             overflow_page = the first page after the last
 *                          one in use
 *   0x00E4E9B6-0x00E4EA00  (page+1)*0x400 >= length (unsigned): grow the
 *                          object with AST_$TRUNCATE(handle, (page+2)*0x400,
 *                          0, &b, status_ret); error -> return; length =
 *                          (page+2)*0x400
 *   0x00E4EA04-0x00E4EA1A  map the page; clear its first word, then kind
 *                          bits = 2 (andi #0x3f / ori #0x80): a link page
 *   0x00E4EA1E-0x00E4EA3A  copy link_len bytes of link_data to page+1
 *   0x00E4EA3E-0x00E4EA6A  uid = handle->uid; AST_$PURIFY(handle, 0x12, 0,
 *                          &page (a longword), 1, status_ret)
 *   0x00E4EA6E-0x00E4EA8C  purify failed: AST_$INVALIDATE(&uid, page, 1,
 *                          TRUE, &private) and keep the purify status
 *
 * Quirks reproduced:
 *   - The directory grows to (page+2)*0x400 bytes, one page beyond the
 *     page it chose, while the grow test uses (page+1)*0x400.
 *   - CRASH_SYSTEM does not return; the decrement after it is unreachable in
 *     practice but present (0x00E4E9AC).
 *   - AST_$TRUNCATE, AST_$PURIFY and AST_$INVALIDATE each get a reserved
 *     Pascal result word nobody reads.
 */

#include "dir/dir_internal.h"

/* `move.l #0x120000,-(SP)' 0x00E4EA5C: AST_$PURIFY flags 0x12, segment 0 */
#define ALLOC_OVF_PURIFY_FLAGS  0x0012

void dir_$alloc_overflow_page(dir_insert_ctx_t *ctx, status_$t *status_ret)
{
    dir_$handle_t *h = (dir_$handle_t *)ARCH_VA_TO_PTR(ctx->handle); /* A3 */
    uint8_t *page;                          /* A0 */
    uint8_t *dst;                           /* A1 */
    uint8_t *src;
    uid_t uid;                              /* A6-0x10 */
    uint32_t page_list;                     /* A6-0x14 */
    status_$t inv_status;                   /* A6-0x20 */
    boolean trunc_result;                   /* A6-0x28 */
    int16_t n;
    int16_t i;

    /* 0x00E4E96E-0x00E4E982 */
    *status_ret = status_$ok;
    ctx->overflow_page = (int16_t)((h->length >> 10) - 1);

    /* 0x00E4E986-0x00E4E9B0 */
    for (;;) {
        page = (uint8_t *)dir_$map_page(h, ctx->overflow_page);
        if (*(uint16_t *)page != 0) {
            break;
        }
        if (ctx->overflow_page == 0) {
            CRASH_SYSTEM(&Naming_bad_request_header_ver_err);
        }
        ctx->overflow_page--;
    }

    /* 0x00E4E9B2 */
    ctx->overflow_page++;

    /* 0x00E4E9B6-0x00E4EA00 */
    if ((((uint32_t)(uint16_t)ctx->overflow_page + 1) << 10) >= h->length) {
        AST_$TRUNCATE(&h->uid,
                      ((uint32_t)(uint16_t)ctx->overflow_page + 2) << 10,
                      0, &trunc_result, status_ret);
        if (*status_ret != status_$ok) {
            return;
        }
        h->length = ((uint32_t)(uint16_t)ctx->overflow_page + 2) << 10;
    }

    /* 0x00E4EA04-0x00E4EA1A */
    page = (uint8_t *)dir_$map_page(h, ctx->overflow_page);
    *(uint16_t *)page = 0;
    page[0] &= 0x3F;
    page[0] |= 0x80;

    /* 0x00E4EA1E-0x00E4EA3A */
    dst = page + 1;
    src = (uint8_t *)ctx->link_data;
    n = (int16_t)(ctx->link_len - 1);
    if (n >= 0) {
        i = 1;
        do {                                /* dbf D0w */
            dst[i - 1] = src[i - 1];
            i++;
        } while (n-- != 0);
    }

    /* 0x00E4EA3E-0x00E4EA6A */
    uid.high = h->uid.high;
    uid.low = h->uid.low;
    page_list = (uint32_t)(uint16_t)ctx->overflow_page;
    AST_$PURIFY(&h->uid, ALLOC_OVF_PURIFY_FLAGS, 0, &page_list, 1, status_ret);

    /* 0x00E4EA6E-0x00E4EA8C */
    if (*status_ret != status_$ok) {
        AST_$INVALIDATE(&uid, (uint32_t)(uint16_t)ctx->overflow_page, 1,
                        (boolean)0xFF, &inv_status);
    }
}
